def run(params, grid, demos):
    separator = int(round(params['rule'][0]))
    foreground = int(round(params['rule'][1]))
    paint = int(round(params['rule'][2]))
    background = int(round(params['rule'][3]))
    direction = int(round(params['rule'][4]))
    if min(separator, foreground, paint, background) < 0 or max(separator, foreground, paint, background) > 9:
        return grid.copy()
    work = grid.T if direction != 0 else grid
    dividers = np.where(np.all(work == separator, axis=0))[0]
    if len(dividers) != 1:
        return grid.copy()
    split = int(dividers[0])
    left = work[:, :split]
    right = work[:, split + 1:]
    if left.shape != right.shape:
        return grid.copy()
    result = np.where(np.logical_and(left == foreground, right == foreground), paint, background)
    return result.T if direction != 0 else result
